mapper.select:
SELECT * FROM v_poi
ORDER BY avg_price IS NULL, avg_price DESC, name ORDER BY avg_price IS NULL, avg_price ASC, name ORDER BY built_year IS NULL, built_year DESC, name ORDER BY built_year IS NULL, built_year ASC, name ORDER BY name ORDER BY type, name
LIMIT #{size} OFFSET #{offset}

SELECT *, ST_Distance_Sphere(POINT(lng, lat), POINT(#{lng}, #{lat})) AS distance FROM v_poi WHERE type = 'bank'
AND branch_type = #{branchType}
AND lat BETWEEN #{lat} - #{radius} / 111000.0 AND #{lat} + #{radius} / 111000.0 AND lng BETWEEN #{lng} - #{radius} / (111000.0 * COS(RADIANS(#{lat}))) AND #{lng} + #{radius} / (111000.0 * COS(RADIANS(#{lat}))) AND ST_Distance_Sphere(POINT(lng, lat), POINT(#{lng}, #{lat})) <= #{radius} ORDER BY distance LIMIT #{limit}
